// Built-in theme presets. Each is a full set of the CSS variables the app
// reads; selecting one writes it to theme.css and injects it live.

export type ThemeVars = Record<string, string>;

// Bumped whenever the token set changes; theme.css files generated by an older
// build (no marker) are regenerated from their preset on startup.
export const THEME_VERSION = "dotmd-theme v3";
/** Same version, stamped before the rename — still current, not regenerated. */
export const LEGACY_THEME_VERSION = "toc-theme v3";

// Interaction washes + depth, split light vs dark so hover/active/selection
// and shadows read correctly on either ground. Ink washes, not iOS greys.
// `--sticker-ring` is the die-cut border around stickers (the "you are here"
// states); `--highlight` fills ==highlighted== text.
const LIGHT_FX = {
  "--hover": "rgba(20, 20, 20, 0.05)",
  "--active": "rgba(20, 20, 20, 0.09)",
  "--active-line": "rgba(20, 20, 20, 0.035)",
  "--shadow-color": "rgba(20, 20, 20, 0.16)",
  "--chip-ink": "#000000", // subject chips mix their colour toward this for text
  "--sticker-ring": "#ffffff",
  "--highlight": "#ffc83d",
  "--scheme": "light", // native controls (date picker, scrollbars)
};
const DARK_FX = {
  "--hover": "rgba(255, 255, 255, 0.06)",
  "--active": "rgba(255, 255, 255, 0.11)",
  "--active-line": "rgba(255, 255, 255, 0.035)",
  "--shadow-color": "rgba(0, 0, 0, 0.55)",
  "--chip-ink": "#ffffff",
  "--sticker-ring": "rgba(255, 255, 255, 0.2)",
  "--highlight": "#e0a823",
  "--scheme": "dark",
};

// Fenced-code syntax palettes.
const SYN_LIGHT = {
  "--syn-keyword": "#ad3da4",
  "--syn-string": "#c41a16",
  "--syn-func": "#3e6d74",
  "--syn-number": "#1c00cf",
  "--syn-comment": "#6c7986",
  "--syn-type": "#0b4f79",
  "--syn-property": "#326d74",
};
const SYN_DARK = {
  "--syn-keyword": "#ff7ab2",
  "--syn-string": "#ff8170",
  "--syn-func": "#67b7a4",
  "--syn-number": "#d9c97c",
  "--syn-comment": "#7f8c98",
  "--syn-type": "#5dd8ff",
  "--syn-property": "#a167e6",
};

// Compact presets: the eight colours that give a theme its character. The rest
// of the token set is derived from them, so every preset stays complete.
type ThemeBase = Record<
  | "--bg"
  | "--panel-bg"
  | "--text"
  | "--muted"
  | "--accent"
  | "--on-accent"
  | "--highlight"
  | "--sticker-ring",
  string
>;

function fromBase(b: ThemeBase, dark: boolean): ThemeVars {
  return {
    ...(dark ? DARK_FX : LIGHT_FX),
    ...(dark ? SYN_DARK : SYN_LIGHT),
    "--grouped": b["--panel-bg"],
    "--card": b["--bg"],
    "--border": `color-mix(in srgb, ${b["--muted"]} 26%, ${b["--panel-bg"]})`,
    // Text/line accent: on light grounds pull it toward the ink so links and
    // tags stay legible; on dark grounds the light accent already is.
    "--accent-strong": dark ? b["--accent"] : `color-mix(in srgb, ${b["--accent"]} 72%, ${b["--text"]})`,
    "--heading": b["--text"],
    "--code-bg": b["--panel-bg"],
    "--selection": `color-mix(in srgb, ${b["--accent"]} 24%, transparent)`,
    "--danger": dark ? "#ff6b5e" : "#d92d20",
    "--success": dark ? "#3ccf8e" : "#1f9d6b",
    ...b,
  };
}

